<template>
  <div class="transRecord">
    <title-line :title="title" />
    <div class="filter">
      <div class="filter-box" @click="showPop=!showPop">
        <div class="text">{{ dateList.find(item=>item.value===currentValue).name }}</div>
        <div class="drow_icon">
          <van-icon name="arrow-down" />
        </div>
      </div>
      <div v-if="showPop" class="typePop">
        <div v-for="item in dateList" :key="item.value" class="filterBox" @click="currentValue=item.value;showPop=false;onRefresh()">
          <div class="text">{{ item.name }}</div>
        </div>
      </div>
    </div>
    <van-tabs v-model="currentIndex" :ellipsis="false" @change="getSubClass">
      <van-tab v-for="item in typeList" :key="item.value" :title="item.label">
        <div class="content">
          <div class="recordList">
            <div class="recordList-header">
              <div class="left">{{ $t('wdsr.wdsr56') }}</div>
              <div class="right">{{ $t('wdsr.wdsr57') }}</div>
            </div>
            <div class="listBox">
              <van-pull-refresh v-model="refreshing" :loading-text="$t('tzjl.tzjl50')" :pulling-text="$t('tzjl.tzjl51')" :loosing-text="$t('tzjl.tzjl52')" :finished-text="$t('tzjl.tzjl53')" @refresh="onRefresh">
                <van-list
                  v-model="loading"
                  :finished="finished"
                  :loading-text="$t('tzjl.tzjl50')"
                  finished-text=""
                  @load="onLoad"
                >
                  <is-empty v-if="dataList.length===0" />
                  <div v-for="(ele ,index) in dataList" :key="index" class="list">
                    <div class="left">
                      <!-- <img class="img" :src="ele.pic" alt=""> -->
                      <div class="kind">
                        <span>{{ ele.title }}</span>
                        <span>{{ ele.time }}</span>
                      </div>
                    </div>
                    <div class="right">
                      <span :style="ele.mons.includes('-')?'color: #fe4854':''"><cite>{{ ele.mons.includes('-')?'':'+' }}</cite>{{ ele.mons }}</span>
                      <span v-if="currentIndex===2">{{ '提至：'+ele.uidto.slice(0,4)+'****'+ele.uidto.slice(ele.uidto.length-4,ele.uidto.length) }}</span>
                      <span class="">{{ ele.status }}</span>
                    </div>
                  </div>
                </van-list>
              </van-pull-refresh>
            </div>
          </div>
          <!-- <div v-if="currentIndex===1" />
          <div v-if="currentIndex===2" />
          <div v-if="currentIndex===3" /> -->
        </div>
      </van-tab>
    </van-tabs>
  </div>
</template>
<script>
import TitleLine from './modules/TitleLine'
import transIcon1 from '@/assets/portal/trans-icon1.png'
import transIcon2 from '@/assets/portal/trans-icon2.png'
import transIcon3 from '@/assets/portal/trans-icon3.png'
import transIcon4 from '@/assets/portal/trans-icon4.png'
import { toprecord, drawrecord, changes, dividend } from '@/api/user'
export default {
  components: {
    TitleLine
  },
  props: {
    // currentValue: {
    //   type: Number,
    //   default: 0
    // }
  },
  data() {
    return {
      title: this.$t('jyjl.jyjl01'),
      showPop: false,
      currentValue: '1',
      dateList: [{ name: this.$t('wdsr.wdsr44'), value: '1' }, { name: this.$t('wdsr.wdsr45'), value: '2' }
      // , { name: '近7天', value: '7' }, { name: '近30天', value: '30' }
      ],
      typeList: [{ label: this.$t('jyjl.jyjl02'), value: 0 }, { label: this.$t('jyjl.jyjl03'), value: 1 }, { label: this.$t('jyjl.jyjl04'), value: 2 }, { label: this.$t('jyjl.jyjl05'), value: 3 }],
      currentIndex: 0,
      dataList: [
        // { pic: transIcon1, title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' },
        // { pic: transIcon1, title: '第三方 > 主账号', time: '2023-09-09 10:21:47', mons: '10.86', status: '转账成功' }
      ],
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10
    }
  },
  created() {
  },
  methods: {
    getSubClass(value, label) {
      this.currentIndex = value
      this.onRefresh()
    },
    async onLoad() {
      let res; let arr = []
      if (this.currentIndex === 0) {
        res = await changes({ type: this.currentValue, pages: this.pageNum })
        arr = res.datalist.map(element => {
          return {
            pic: transIcon3,
            title: element.gametypename,
            time: element.ctime,
            mons: element.cmons,
            status: '余额：' + element.umons
          }
        })
      } else if (this.currentIndex === 1) {
        res = await toprecord({ type: this.currentValue, pages: this.pageNum })
        arr = res.datalist.map(element => {
          return {
            pic: transIcon1,
            title: element.title,
            time: element.paytime,
            mons: element.cmons,
            status: element.pstatus
          }
        })
      } else if (this.currentIndex === 2) {
        res = await drawrecord({ type: this.currentValue, pages: this.pageNum })
        arr = res.datalist.map(element => {
          return {
            pic: transIcon2,
            title: element.title,
            time: element.paytime,
            mons: element.cmons,
            uidto: element.uidto,
            status: element.pstatus
          }
        })
      } else if (this.currentIndex === 3) {
        res = await dividend({ type: this.currentValue, pages: this.pageNum })
        arr = res.datalist.map(element => {
          return {
            pic: transIcon4,
            title: element.title,
            time: element.ctime,
            mons: element.cmons,
            status: element.cname
          }
        })
      }
      // this.dataList = res.datalist
      if (this.refreshing) {
        this.dataList = []
        this.refreshing = false
      }
      this.dataList = this.dataList.concat(arr)
      this.loading = false
      this.pageNum++
      if (this.dataList.length >= Number(res.totalrow)) {
        this.finished = true
      }
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    }
  }

}
</script>
<style lang="less">
