    min-height: 100vh;
    width: 100%;
    // background: #19223b;
    background: var(--inner-bg-color);
    background-size: 100% 100%;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
    .filter {
        position: absolute;
        top: 16px;
        right: 16px;
        z-index: 9999;
        min-width: 20%;
        height: 60px;
        line-height: 60px;
        // border: 1px solid #283249;
        border-color: rgba(#f4eeff31);
        border-style: solid;
        border-width: 2px;
        border-radius: 12px;
        .filter-box {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                    .text {
                        margin-left: 20px;
                    }
                    .drow_icon{
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        width: 40px;
                        height: 40px;
                        margin-right: 20px;
                        background: rgba(255,255,255,0.12);
                        border-radius: 8.6px;
                        // background-image: url(~@/assets/portal/drow.png);
                        // background-position: 0% 0%;
                        // background-size: 100% 100%;
                        // background-repeat: no-repeat;
                    }
                }
                .typePop {
                    position: relative;
                    background: #404f7163;
                    // background: rgba($color: #28334d, $alpha: 0.16);
                    border-radius: 20px;
                    z-index: 1000;
                    margin-top: 4px;
                    .filterBox {
                        font-size: 26px;
                        .text {
                            text-align: center;
                        }
                    }
                }
    }
    .content {
        padding: 28px 28px 24px;
        .recordList {
            width: 100%;
            height: 1354px;
            // background: #202a41;
            border-radius: 26px;
            height: 1354px;
            .recordList-header {
                display: flex;
                justify-content: space-between;
                align-items: center;
                height: 80px;
                padding: 0 24px;
                background: rgba(223,226,253,0.12);
                border-radius: 12px;
            }
            .listBox {
                height: 100%;
                padding: 0 ;
                overflow: auto;
                .list {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                    padding: 24px 0;
                    box-shadow: inset 0 -2px 0 0 rgba(255,255,255,0.12);
                    // border-bottom: 1px solid #3e485c;
                    // border-bottom-color: #3e485c;
                    // border-bottom-style: solid;
                    // border-bottom-width: 2px;
                    .green {
                        color: #56ae85!important;
                    }
                    .left {
                        display: flex;
                        align-items: center;
                        .img{
                            width: 66px;
