                        }
                        .kind {
                            display: flex;
                            flex-direction: column;
                            margin-left: 20px;
                            span:first-child {
                                font-family: PingFangSC-Semibold;
                                font-size: 28px;
                                color: #FFFFFF;
                                letter-spacing: 0;
                                font-weight: 500;
                            }
                            span {
                                margin-top: 10px;
                                font-family: PingFangSC-Regular;
                                font-size: 24px;
                                color: rgba(255, 255, 255,0.75);
                                letter-spacing: 0;
                                font-weight: 400;
                            }
                        }
                    }
                    .right {
                        display: flex;
                        flex-direction: column;
                        span:first-child {
                            font-family: PingFangSC-Semibold;
                            font-size: 28px;
                            color: #1DEEA7;
                            letter-spacing: 0;
                            text-align: right;
                            font-weight: 700;
                        }
                        span:last-child {
                            margin-top: 14px;
                            font-family: PingFangSC-Semibold;
                            font-size: 24px;
                            color: #FFD700;
                            letter-spacing: 0;
                            text-align: right;
                            font-weight: 400;
                        }
                        span {
                            font-size: 20px;
                            font-weight: 400;
                            color: #7987a7;
                            text-align: right;
                        }
                    }
                }
            }
        }
    }
    .van-tabs__nav{
        background: none;
    }
    .van-tab--active {
        color: #fff !important;
    }
    .van-tab{
        color:#7582a2;
        width: 156px;
        font-size: 24px;
        font-weight: 600;
        padding: 0;
    }
    .van-tabs__line {
        background-image: var(--btn-bg-color);
        border-radius: 1px;
        width: 25%;
        height: 4px;
    }
}
